parameters.content:
{
  "id": "a7a62cbf-e87d-4706-909d-509bfde17de1",
  "version": "1.8",
  "name": "CustomerEscalationTriage",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Manual trigger"
      },
      "inputs": {
        "entryPointId": "23476fbe-a4ff-453e-be3c-3074a0262270",
        "isDefaultEntryPoint": true
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Data passed when manually triggering the workflow.",
          "source": "null",
          "var": "output"
        }
      }
    },
    {
      "id": "checkProductionDown",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Production Down?"
      },
      "inputs": {
        "expression": "$vars.start.output.productionDown === true",
        "trueLabel": "Yes",
        "falseLabel": "No"
      }
    },
    {
      "id": "checkCriticalFlag",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Critical Tier or Impact?"
      },
      "inputs": {
        "expression": "$vars.start.output.customerTier === \"Enterprise\" || $vars.start.output.businessImpact === \"critical\"",
        "trueLabel": "Critical",
        "falseLabel": "Non-Critical"
      }
    },
    {
      "id": "checkWorkaround",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Workaround Available?"
      },
      "inputs": {
        "expression": "$vars.start.output.workaroundAvailable === true",
        "trueLabel": "Yes",
        "falseLabel": "No"
      }
    },
    {
      "id": "classifyP1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Classify P1 - Critical"
      },
      "inputs": {
        "script": "const caseKey = $vars.start.output.correlationId + \"-P1\";\nreturn {\n  severity: \"P1\",\n  engineeringNeeded: true,\n  responseMode: \"immediate\",\n  caseKey: caseKey\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "P1 classification result",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "classifyP2",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Classify P2 - Production Down, No Workaround"
      },
      "inputs": {
        "script": "const caseKey = $vars.start.output.correlationId + \"-P2\";\nconst engineeringNeeded = $vars.start.output.customerTier === \"Enterprise\";\nreturn {\n  severity: \"P2\",\n  engineeringNeeded: engineeringNeeded,\n  responseMode: \"urgent\",\n  caseKey: caseKey\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "P2 classification result",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "classifyP3",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Classify P3 - Production Down, Workaround Exists"
      },
      "inputs": {
        "script": "const caseKey = $vars.start.output.correlationId + \"-P3\";\nreturn {\n  severity: \"P3\",\n  engineeringNeeded: false,\n  responseMode: \"standard\",\n  caseKey: caseKey\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "P3 classification result",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "classifyP4",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Classify P4 - No Production Impact"
      },
      "inputs": {
        "script": "const caseKey = $vars.start.output.correlationId + \"-P4\";\nreturn {\n  severity: \"P4\",\n  engineeringNeeded: false,\n  responseMode: \"low\",\n  caseKey: caseKey\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "P4 classification result",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "endP1",
      "type": "core.control.end",
